/**
 * 03 练习册的四本分类本：语言 / 词汇 / 写作 / 翻译。
 * 每本对应一张独立题卷 —— 题库按材料整编、按题类排队（见 banks/），
 * 页面上只做题、不讲知识，和 02 知识库的书页分开。
 */
export interface PracticeTrack {
  id: string;
  title: string;
  titleZh: string;
  subtitleZh: string;
  /** 题库旁边那本知识书的 id（「去看知识书」与台账用）。 */
  bookId: string;
  accent: string;
}

export const PRACTICE_TRACKS: PracticeTrack[] = [
  {
    id: "language",
    title: "Language Drills",
    titleZh: "语言",
    subtitleZh: "语言学各章的判断、填空与术语问答，按题型排队练。",
    bookId: "knowledge-linguistics",
    accent: "#7f6d5f",
  },
  {
    id: "vocabulary",
    title: "Vocabulary Drills",
    titleZh: "词汇",
    subtitleZh: "构词、辨析与搭配分头练，再加一组综合演练。",
    bookId: "knowledge-vocabulary",
    accent: "#b28b42",
  },
  {
    id: "writing",
    title: "Writing Drills",
    titleZh: "写作",
    subtitleZh: "句子纠错、句式变换、段落诊断，还有范例对照。",
    bookId: "knowledge-writing",
    accent: "#8a6d9c",
  },
  {
    id: "translation",
    title: "Translation Drills",
    titleZh: "翻译",
    subtitleZh: "汉译英与英译汉的段落练习，一段一段对照译文。",
    bookId: "knowledge-translation",
    accent: "#5f7d8a",
  },
];

export function practiceTrackById(id: string | undefined) {
  return PRACTICE_TRACKS.find((track) => track.id === id);
}

/** 知识书页上「去练习册」用的反向对照。 */
export const TRACK_BY_BOOK: Record<string, string> = Object.fromEntries(
  PRACTICE_TRACKS.map((track) => [track.bookId, track.id]),
);
